window.ASTERWIND_SCENARIOS = {"schemaVersion": "1.0.0", "contentStatus": "source_grounded_content_and_proposed_presentation_copy", "source": {"filename": "Leadership Quiz Revised.xlsx", "sha256": "a55072c8c5aa9c1a9d1bfaccc539f3d0b92be45c94bda38310635da9defa43a6", "attribution": "Amanda created the original quiz workbook; Hannah refined content, shortened feedback, fixed the balance check, and added screen copy, coding handoff and playtest plan. No per-scenario authorship is asserted.", "attributionBasis": "Hannah message shared by Bob on 25 October 2026", "readOnly": true}, "uiPolicy": {"preserveExistingInterface": true, "visualDirection": "User-approved paper theatre, existing sticker-note treatment and bottom-right choice structure; do not redesign.", "factsAndTextLayer": "Render all readable facts, questions, labels, feedback and captions as accessible HTML, not generated image/video text.", "choiceOptionsFullMode": 4, "showStyleBeforeChoice": false, "moralScore": false, "personalityDiagnosis": false, "clickFeedback": "Change selected state and show acknowledgement immediately, independently of media loading.", "feedbackPlacement": "Reuse the existing bottom-right note/choice area; one focal message at a time.", "sourceOptionAvailability": "Keep the complete source option text available alongside the short label in full mode; never replace source meaning with an opaque label.", "noSelection": "Continue without choosing is neutral; do not record an option or assign a style.", "mediaFallback": "Keep the approved still and HTML text if a clip is missing, loading, fails, or reduced motion is requested. No clip is required to finish a scene.", "endingHonesty": "A shared reflection is not proof all real choices have the same outcome. No fabricated grade, event success or personality result.", "evaluationTiming": "The original full quiz recommends feedback after all nine answers. This narrative exploration intentionally offers immediate consequence/feedback; label it as an adaptation, not the unchanged nine-question assessment."}, "modes": {"allNine": {"label": "Explore all nine situations", "scenarioIds": ["Q1", "Q2", "Q3", "Q4", "Q5", "Q6", "Q7", "Q8", "Q9"], "optionPolicy": "all_source_options", "timed": false, "completionTimeClaim": null, "description": "Untimed exploration. No claim that all nine films plus discussion fit five minutes. No aggregated personality score."}, "quickDemo": {"label": "Quick demo — two-option adaptation", "scenarioIds": ["Q5"], "optionIds": ["Q5A", "Q5C"], "omittedOptionIds": ["Q5B", "Q5D"], "isAdaptation": true, "disclosure": "This short demo compares two of the workbook’s four responses. Explore the full situation to see all four.", "timed": false, "fiveMinuteEncounterTarget": {"launch": 20, "setupAndContext": 55, "choice": 25, "feedbackAndConsequence": 40, "sharedReflection": 40, "discussion": 80, "technicalReserve": 40, "totalSeconds": 300, "status": "design_budget_not_measured_result"}}, "curatedContrast": {"label": "Optional two-scene discussion path", "scenarioIds": ["Q5", "Q3"], "optionPolicy": "all_source_options", "isAdaptation": true, "rationale": "Contrast time for development with ten-minute urgency. These are independent situations, not a causal story.", "fiveMinuteEncounterTarget": {"launch": 20, "q5Context": 35, "q5Choice": 25, "q5Feedback": 25, "transition": 10, "q3Context": 30, "q3Choice": 20, "q3Feedback": 25, "discussion": 80, "technicalReserve": 30, "totalSeconds": 300, "status": "optional_design_budget_rehearsal_required"}, "fallbackIfTooLong": "Use Q5 alone; never speed through source options or remove discussion to force the total."}}, "scenarios": [{"id": "Q1", "title": "The Unreachable Teammate", "scenarioText": "You're on a student society's committee and everyone is buried in midterms. One committee member hasn't replied to the group chat or your DMs in nearly a week. Your next event is coming up and their tasks are still undone. What are you most likely to do?", "stakes": "Protect the event without judging an absent teammate before understanding what happened.", "sourceFacts": ["You are on a student society committee.", "Everyone is busy with midterms.", "One member has not replied to the group chat or your DMs in nearly a week.", "The next event is approaching and that member’s tasks remain undone."], "options": [{"id": "Q1A", "key": "A", "buttonLabel": "Cover their tasks for now", "sourceText": "Take over their tasks this week so the event isn't affected, and raise it with them once the event is over.", "buttonLabelStatus": "faithful_short_display_adaptation", "acknowledgement": "You chose: cover their tasks for now.", "feedback": "You protected the deadline, but taking over may hide the reason for the silence and add to your own workload. This works when time is almost gone, not as a first response.", "feedbackStatus": "verbatim_workbook", "consequence": "You cover the immediate work, but the reason for the silence may remain unresolved.", "consequenceStatus": "proposed_possible_consequence_not_observed_outcome", "reflectionPrompt": "What would you need to know before reassigning the work, and how long can the event afford to wait?", "workbookInterpretation": {"style": "Pacesetting", "suggestedForGivenFacts": false, "attribution": "Workbook interpretation, not a validated diagnosis or universal moral score", "sourceCells": {"option": "Quiz!D5", "feedback": "Coding Handoff!H2", "style": "Coding Handoff!F2"}}}, {"id": "Q1B", "key": "B", "buttonLabel": "Ask the committee to share tasks", "sourceText": "Post in the committee chat that their tasks are uncovered and ask everyone to say what they can take on.", "buttonLabelStatus": "faithful_short_display_adaptation", "acknowledgement": "You chose: ask the committee to share tasks.", "feedback": "You shared the problem with the group, but doing so publicly may embarrass the teammate and leave ownership unclear. Group input works better after someone has checked what happened.", "feedbackStatus": "verbatim_workbook", "consequence": "The uncovered work becomes visible to everyone; the teammate may feel exposed before being heard.", "consequenceStatus": "proposed_possible_consequence_not_observed_outcome", "reflectionPrompt": "What would you need to know before reassigning the work, and how long can the event afford to wait?", "workbookInterpretation": {"style": "Democratic", "suggestedForGivenFacts": false, "attribution": "Workbook interpretation, not a validated diagnosis or universal moral score", "sourceCells": {"option": "Quiz!E5", "feedback": "Coding Handoff!H3", "style": "Coding Handoff!F3"}}}, {"id": "Q1C", "key": "C", "buttonLabel": "Reach out and check on them", "sourceText": "Try another way to reach them, like a call or a friend who lives nearby, and ask how they're doing before deciding anything.", "buttonLabelStatus": "faithful_short_display_adaptation", "acknowledgement": "You chose: reach out and check on them.", "feedback": "You checked the situation before judging it. This protects trust and gives you useful information, as long as you also set a clear time for a reply and a backup plan.", "feedbackStatus": "verbatim_workbook", "consequence": "You seek information before judging; the event still needs a reply deadline and a backup plan.", "consequenceStatus": "proposed_possible_consequence_not_observed_outcome", "reflectionPrompt": "What would you need to know before reassigning the work, and how long can the event afford to wait?", "workbookInterpretation": {"style": "Affiliative", "suggestedForGivenFacts": true, "attribution": "Workbook interpretation, not a validated diagnosis or universal moral score", "sourceCells": {"option": "Quiz!F5", "feedback": "Coding Handoff!H4", "style": "Coding Handoff!F4"}}}, {"id": "Q1D", "key": "D", "buttonLabel": "Escalate and reassign with deadlines", "sourceText": "Tell the director today and reassign the tasks with deadlines, so the event has a clear plan.", "buttonLabelStatus": "faithful_short_display_adaptation", "acknowledgement": "You chose: escalate and reassign with deadlines.", "feedback": "You created clarity quickly, which may be necessary if the deadline is close. As a first step, though, it may overlook a genuine personal problem or work already in progress.", "feedbackStatus": "verbatim_workbook", "consequence": "The work gets new owners quickly, but you may act before learning what caused the silence.", "consequenceStatus": "proposed_possible_consequence_not_observed_outcome", "reflectionPrompt": "What would you need to know before reassigning the work, and how long can the event afford to wait?", "workbookInterpretation": {"style": "Commanding", "suggestedForGivenFacts": false, "attribution": "Workbook interpretation, not a validated diagnosis or universal moral score", "sourceCells": {"option": "Quiz!G5", "feedback": "Coding Handoff!H5", "style": "Coding Handoff!F5"}}}], "reflectionPrompt": "What would you need to know before reassigning the work, and how long can the event afford to wait?", "workbookInterpretation": {"suggestedOptionId": "Q1C", "style": "Affiliative", "concepts": "Unstated expectations; diffusion of responsibility; 'people come first' (Affiliative) with a deadline", "caseStudyConnections": "Conflicts in Prague (Leadership Styles reading); the Assigned Leader mini-case about a team member who isn't pulling their weight", "rationale": "A week of silence during midterms is more likely overload or a personal problem than apathy, and right now you don't know which. A check-in is information-gathering: they may be nearly done, ill, or never knew the deadline. Looking back at the Prague case from class, the manager there supported stressed colleagues because stress, not incompetence, was the cause. Midterms play that role here.", "keyLesson": "Check in first, but give it a clock (24-48 hours). Without one, it becomes people-pleasing; with one, it is fair to the person and to the event. Escalate if there's no response.", "situationalCaveat": "If the event is tonight, covering the tasks or escalating becomes more reasonable.", "sourceRange": "Question Feedback!A2:J2", "status": "Workbook interpretation; course references need group verification"}, "media": {"stillFilename": "Q1-Unreachable-Teammate.png", "videoFilename": "q1-setup-v01.mp4", "videoRequired": false, "videoStatus": "not_generated", "alt": "Illustrative paper-theatre scene for The Unreachable Teammate.", "sourceFidelityNote": "The empty chair is illustrative; do not invent why the teammate is absent or a reply from them.", "referenceStillPath": "production/reference-stills/Q1-Unreachable-Teammate.png"}, "sourceRange": "Quiz!A5:G5", "sharedReflection": "Different approaches reveal different trade-offs. Consider what extra information or change in circumstances would alter your response."}, {"id": "Q2", "title": "The Late Dancer", "scenarioText": "You're leading your dance team for the end-of-semester performance. One member keeps arriving late and delaying rehearsals for everyone else, which is unfair to the rest of the team. What are you most likely to do?", "stakes": "Protect fair rehearsal time while addressing one person’s lateness constructively.", "sourceFacts": ["You lead a dance team preparing an end-of-semester performance.", "One member repeatedly arrives late.", "Their lateness delays rehearsals and affects the rest of the team."], "options": [{"id": "Q2A", "key": "A", "buttonLabel": "Talk privately about the lateness", "sourceText": "Pull them aside after rehearsal, describe what you've noticed and what it's doing to the group, and ask what's making it hard to get there on time.", "buttonLabelStatus": "faithful_short_display_adaptation", "acknowledgement": "You chose: talk privately about the lateness.", "feedback": "You addressed the issue privately, explained its impact and made space for the person’s side. This combines accountability with support and gives you a basis for the next step.", "feedbackStatus": "verbatim_workbook", "consequence": "The specific behaviour and its impact are named privately, with room to understand its cause.", "consequenceStatus": "proposed_possible_consequence_not_observed_outcome", "reflectionPrompt": "How would you combine support for this person with fairness to everyone who arrived on time?", "workbookInterpretation": {"style": "Coaching", "suggestedForGivenFacts": true, "attribution": "Workbook interpretation, not a validated diagnosis or universal moral score", "sourceCells": {"option": "Quiz!D6", "feedback": "Coding Handoff!H6", "style": "Coding Handoff!F6"}}}, {"id": "Q2B", "key": "B", "buttonLabel": "Remind everyone of the shared goal", "sourceText": "Open the next rehearsal by reminding the whole team what the performance means and why every minute counts.", "buttonLabelStatus": "faithful_short_display_adaptation", "acknowledgement": "You chose: remind everyone of the shared goal.", "feedback": "You reminded everyone of the shared goal, but the message is indirect. The person who is late may not realize the concern is about them, while others may feel unfairly lectured.", "feedbackStatus": "verbatim_workbook", "consequence": "The group hears a shared purpose, but the late member may not recognize the specific change needed.", "consequenceStatus": "proposed_possible_consequence_not_observed_outcome", "reflectionPrompt": "How would you combine support for this person with fairness to everyone who arrived on time?", "workbookInterpretation": {"style": "Visionary", "suggestedForGivenFacts": false, "attribution": "Workbook interpretation, not a validated diagnosis or universal moral score", "sourceCells": {"option": "Quiz!E6", "feedback": "Coding Handoff!H7", "style": "Coding Handoff!F7"}}}, {"id": "Q2C", "key": "C", "buttonLabel": "Keep rehearsal pressure low", "sourceText": "Keep rehearsals relaxed and tell them you understand everyone is swamped, so they don't feel extra pressure.", "buttonLabelStatus": "faithful_short_display_adaptation", "acknowledgement": "You chose: keep rehearsal pressure low.", "feedback": "You reduced pressure, but the rest of the team continues to absorb the cost. Support matters, yet it should come with a direct conversation about what needs to change.", "feedbackStatus": "verbatim_workbook", "consequence": "Pressure may ease for the late member while the rest of the team continues to lose rehearsal time.", "consequenceStatus": "proposed_possible_consequence_not_observed_outcome", "reflectionPrompt": "How would you combine support for this person with fairness to everyone who arrived on time?", "workbookInterpretation": {"style": "Affiliative", "suggestedForGivenFacts": false, "attribution": "Workbook interpretation, not a validated diagnosis or universal moral score", "sourceCells": {"option": "Quiz!F6", "feedback": "Coding Handoff!H8", "style": "Coding Handoff!F8"}}}, {"id": "Q2D", "key": "D", "buttonLabel": "Model punctuality and start on time", "sourceText": "Arrive early and start every rehearsal exactly on time, so the standard is visible.", "buttonLabelStatus": "faithful_short_display_adaptation", "acknowledgement": "You chose: model punctuality and start on time.", "feedback": "You modelled the standard you want, but example alone may not change the behavior. The expectation and its impact still need to be stated clearly.", "feedbackStatus": "verbatim_workbook", "consequence": "The expected standard is visible, but the cause of the lateness may remain unaddressed.", "consequenceStatus": "proposed_possible_consequence_not_observed_outcome", "reflectionPrompt": "How would you combine support for this person with fairness to everyone who arrived on time?", "workbookInterpretation": {"style": "Pacesetting", "suggestedForGivenFacts": false, "attribution": "Workbook interpretation, not a validated diagnosis or universal moral score", "sourceCells": {"option": "Quiz!G6", "feedback": "Coding Handoff!H9", "style": "Coding Handoff!F9"}}}], "reflectionPrompt": "How would you combine support for this person with fairness to everyone who arrived on time?", "workbookInterpretation": {"suggestedOptionId": "Q2A", "style": "Coaching", "concepts": "SBI feedback (Situation, Behaviour, Impact); sandwich method vs direct feedback; unstated expectations; people-pleasing", "caseStudyConnections": "The Marriott case study from class (the expectation, evaluation, feedback cycle); Two Tough Calls (clear, direct feedback)", "rationale": "Feedback is the step most organisations skip. A private conversation using SBI tells the person exactly what happened and what it caused, without the defensiveness the 'sandwich method' (praise, criticism, praise) tends to create. Example: 'In the last three rehearsals (situation), you arrived about 20 minutes late (behaviour), and the group lost practice time (impact).' Then ask what's going on, because lateness often has causes you can't see: a class clash, a job, a bad week.", "keyLesson": "Be specific, be private, describe the impact, then listen.", "situationalCaveat": "If lateness continues after a clear conversation, firmer consequences become appropriate.", "sourceRange": "Question Feedback!A3:J3", "status": "Workbook interpretation; course references need group verification"}, "media": {"stillFilename": "Q2-Late-Dancer.png", "videoFilename": "q2-setup-v01.mp4", "videoRequired": false, "videoStatus": "not_generated", "alt": "Illustrative paper-theatre scene for The Late Dancer.", "sourceFidelityNote": "The arriving figure is proposed staging, not a source claim about motive or personal circumstances.", "referenceStillPath": "production/reference-stills/Q2-Late-Dancer.png"}, "sourceRange": "Quiz!A6:G6", "sharedReflection": "Different approaches reveal different trade-offs. Consider what extra information or change in circumstances would alter your response."}, {"id": "Q3", "title": "The Emergency", "scenarioText": "It's 6:50pm. Your society's biggest event of the semester starts at 7:00 and the lecture theatre projector just died. Five committee members are standing around chatting and scrolling. Guests are already queuing outside. What are you most likely to do?", "stakes": "Use the remaining ten minutes and the team’s capacity before guests enter.", "sourceFacts": ["The current time is 6:50 pm; the event starts at 7:00 pm.", "The lecture theatre projector has just failed.", "Five committee members are standing around chatting or scrolling.", "Guests are already queuing outside."], "options": [{"id": "Q3A", "key": "A", "buttonLabel": "Rally the team around the purpose", "sourceText": "Pull everyone together and remind them why this event matters to the society and to the guests outside.", "buttonLabelStatus": "faithful_short_display_adaptation", "acknowledgement": "You chose: rally the team around the purpose.", "feedback": "You brought attention back to purpose, but the team already knows why the event matters. With ten minutes left, they need clear tasks more than motivation.", "feedbackStatus": "verbatim_workbook", "consequence": "The team hears why the event matters, but urgent jobs may still have no owners.", "consequenceStatus": "proposed_possible_consequence_not_observed_outcome", "reflectionPrompt": "What changes if you have thirty minutes instead of ten?", "workbookInterpretation": {"style": "Visionary", "suggestedForGivenFacts": false, "attribution": "Workbook interpretation, not a validated diagnosis or universal moral score", "sourceCells": {"option": "Quiz!D7", "feedback": "Coding Handoff!H10", "style": "Coding Handoff!F10"}}}, {"id": "Q3B", "key": "B", "buttonLabel": "Ask for ideas and decide together", "sourceText": "Ask the committee for quick ideas on how to fix it and go with what the group lands on.", "buttonLabelStatus": "faithful_short_display_adaptation", "acknowledgement": "You chose: ask for ideas and decide together.", "feedback": "You invited ideas, which can improve buy-in, but an open discussion uses time the team does not have. A very brief idea check could work if one person still makes the call.", "feedbackStatus": "verbatim_workbook", "consequence": "More ideas become available, but discussion uses some of the ten remaining minutes.", "consequenceStatus": "proposed_possible_consequence_not_observed_outcome", "reflectionPrompt": "What changes if you have thirty minutes instead of ten?", "workbookInterpretation": {"style": "Democratic", "suggestedForGivenFacts": false, "attribution": "Workbook interpretation, not a validated diagnosis or universal moral score", "sourceCells": {"option": "Quiz!E7", "feedback": "Coding Handoff!H11", "style": "Coding Handoff!F11"}}}, {"id": "Q3C", "key": "C", "buttonLabel": "Troubleshoot the projector yourself", "sourceText": "Start troubleshooting the projector yourself right away, showing the others what to do.", "buttonLabelStatus": "faithful_short_display_adaptation", "acknowledgement": "You chose: troubleshoot the projector yourself.", "feedback": "You acted immediately, but the rest of the team may remain passive while you become the only problem-solver. In a crisis, using everyone’s capacity matters.", "feedbackStatus": "verbatim_workbook", "consequence": "You begin the repair effort while other urgent jobs may still wait for someone to act.", "consequenceStatus": "proposed_possible_consequence_not_observed_outcome", "reflectionPrompt": "What changes if you have thirty minutes instead of ten?", "workbookInterpretation": {"style": "Pacesetting", "suggestedForGivenFacts": false, "attribution": "Workbook interpretation, not a validated diagnosis or universal moral score", "sourceCells": {"option": "Quiz!F7", "feedback": "Coding Handoff!H12", "style": "Coding Handoff!F12"}}}, {"id": "Q3D", "key": "D", "buttonLabel": "Assign urgent jobs and check back", "sourceText": "Name one person for each urgent job (backup projector, venue contact, the queue) and ask for updates in five minutes.", "buttonLabelStatus": "faithful_short_display_adaptation", "acknowledgement": "You chose: assign urgent jobs and check back.", "feedback": "You gave each urgent task a clear owner and set a check-back time. This is a strong use of direct leadership in a genuine time-sensitive crisis.", "feedbackStatus": "verbatim_workbook", "consequence": "Each urgent job has an owner and a check-back time; the equipment problem is not yet guaranteed solved.", "consequenceStatus": "proposed_possible_consequence_not_observed_outcome", "reflectionPrompt": "What changes if you have thirty minutes instead of ten?", "workbookInterpretation": {"style": "Commanding", "suggestedForGivenFacts": true, "attribution": "Workbook interpretation, not a validated diagnosis or universal moral score", "sourceCells": {"option": "Quiz!G7", "feedback": "Coding Handoff!H13", "style": "Coding Handoff!F13"}}}], "reflectionPrompt": "What changes if you have thirty minutes instead of ten?", "workbookInterpretation": {"suggestedOptionId": "Q3D", "style": "Commanding", "concepts": "Commanding style in a crisis; diffusion of responsibility; matching style to situation", "caseStudyConnections": "The fire alarm case from the Leadership Styles reading", "rationale": "This is the fire alarm situation: everyone waited for someone to take charge until a bystander finally shouted. The more people present, the less likely any one person acts. Your idle committee members don't need inspiration or a discussion, they need to know who does what. Commanding, used at the right moment, is exactly what the situation calls for.", "keyLesson": "With a ticking clock, clear direction beats consensus. Commanding is a tool for crises, not a default: your post-event debrief should look completely different.", "situationalCaveat": "With 30+ minutes, a quick round of ideas could work. Without a crisis, overusing commanding leaves people feeling repressed and stops them speaking up.", "sourceRange": "Question Feedback!A4:J4", "status": "Workbook interpretation; course references need group verification"}, "media": {"stillFilename": "Q3-Emergency.png", "videoFilename": "q3-setup-v01.mp4", "videoRequired": false, "videoStatus": "not_generated", "alt": "Illustrative paper-theatre scene for The Emergency.", "sourceFidelityNote": "The existing still shows three foreground people already investigating equipment, while the source says five committee members are idle. Treat this as a response illustration, not a literal depiction of the pre-choice moment. The source facts remain in HTML; do not show the repair succeeding.", "referenceStillPath": "production/reference-stills/Q3-Emergency.png"}, "sourceRange": "Quiz!A7:G7", "sharedReflection": "Different approaches reveal different trade-offs. Consider what extra information or change in circumstances would alter your response."}, {"id": "Q4", "title": "After a Disappointing Event", "scenarioText": "Your society spent six weeks planning its flagship event, and only 12 people showed up. The feedback form is brutal, the group chat has gone silent, and two committee members are hinting they won't run again next semester. What are you most likely to do?", "stakes": "Help a discouraged team decide whether its effort is still worth continuing.", "sourceFacts": ["The society spent six weeks preparing its flagship event.", "Only 12 people attended.", "The feedback is harsh and the group chat is silent.", "Two committee members are suggesting they will not run again next semester."], "options": [{"id": "Q4A", "key": "A", "buttonLabel": "Set tougher targets next time", "sourceText": "Set tougher targets for the next event and ask everyone to bring the same effort the planning team put in this time.", "buttonLabelStatus": "faithful_short_display_adaptation", "acknowledgement": "You chose: set tougher targets next time.", "feedback": "You raised expectations, but a discouraged team may hear this as blame. Higher standards help when people are motivated, not when they are questioning whether the effort is worthwhile.", "feedbackStatus": "verbatim_workbook", "consequence": "Expectations rise, but a discouraged team may experience the message as blame.", "consequenceStatus": "proposed_possible_consequence_not_observed_outcome", "reflectionPrompt": "Does this team first need rest, a renewed purpose, or a concrete improvement plan?", "workbookInterpretation": {"style": "Pacesetting", "suggestedForGivenFacts": false, "attribution": "Workbook interpretation, not a validated diagnosis or universal moral score", "sourceCells": {"option": "Quiz!D8", "feedback": "Coding Handoff!H14", "style": "Coding Handoff!F14"}}}, {"id": "Q4B", "key": "B", "buttonLabel": "Debrief and reconnect to purpose", "sourceText": "Hold a debrief that treats the flop as a lesson and ties it to a bigger goal for the society.", "buttonLabelStatus": "faithful_short_display_adaptation", "acknowledgement": "You chose: debrief and reconnect to purpose.", "feedback": "You turned failure into a learning point and reconnected the team to a larger purpose. That gives people a reason to improve rather than simply asking them to work harder.", "feedbackStatus": "verbatim_workbook", "consequence": "The team can connect what happened to a larger purpose and identify what to learn next.", "consequenceStatus": "proposed_possible_consequence_not_observed_outcome", "reflectionPrompt": "Does this team first need rest, a renewed purpose, or a concrete improvement plan?", "workbookInterpretation": {"style": "Visionary", "suggestedForGivenFacts": true, "attribution": "Workbook interpretation, not a validated diagnosis or universal moral score", "sourceCells": {"option": "Quiz!E8", "feedback": "Coding Handoff!H15", "style": "Coding Handoff!F15"}}}, {"id": "Q4C", "key": "C", "buttonLabel": "Reconnect over hotpot first", "sourceText": "Organise a casual hotpot night so people can vent and reconnect, and leave planning until everyone feels better.", "buttonLabelStatus": "faithful_short_display_adaptation", "acknowledgement": "You chose: reconnect over hotpot first.", "feedback": "You created space for the team to recover and reconnect. That may be needed first, but morale alone will not answer what the group should learn or do differently.", "feedbackStatus": "verbatim_workbook", "consequence": "People get space to reconnect; a later conversation is still needed about what to change.", "consequenceStatus": "proposed_possible_consequence_not_observed_outcome", "reflectionPrompt": "Does this team first need rest, a renewed purpose, or a concrete improvement plan?", "workbookInterpretation": {"style": "Affiliative", "suggestedForGivenFacts": false, "attribution": "Workbook interpretation, not a validated diagnosis or universal moral score", "sourceCells": {"option": "Quiz!F8", "feedback": "Coding Handoff!H16", "style": "Coding Handoff!F16"}}}, {"id": "Q4D", "key": "D", "buttonLabel": "Review each member’s development", "sourceText": "Meet each committee member one-on-one to review what went wrong for them and what they want to improve.", "buttonLabelStatus": "faithful_short_display_adaptation", "acknowledgement": "You chose: review each member’s development.", "feedback": "You invested in each person’s learning, which can improve future performance. However, individual development may not fully address a team-wide loss of confidence and purpose.", "feedbackStatus": "verbatim_workbook", "consequence": "Individuals receive attention, while the team-wide question of purpose may remain open.", "consequenceStatus": "proposed_possible_consequence_not_observed_outcome", "reflectionPrompt": "Does this team first need rest, a renewed purpose, or a concrete improvement plan?", "workbookInterpretation": {"style": "Coaching", "suggestedForGivenFacts": false, "attribution": "Workbook interpretation, not a validated diagnosis or universal moral score", "sourceCells": {"option": "Quiz!G8", "feedback": "Coding Handoff!H17", "style": "Coding Handoff!F17"}}}], "reflectionPrompt": "Does this team first need rest, a renewed purpose, or a concrete improvement plan?", "workbookInterpretation": {"suggestedOptionId": "Q4B", "style": "Visionary", "concepts": "Crisis presents opportunity; purpose and intrinsic motivation; Visionary style", "caseStudyConnections": "The Marriott case study from class (the resort after the 2004 tsunami); the Martin Luther King Jr. case (people followed him through his own doubts because they believed in the purpose)", "rationale": "The Marriott leader first looked after his team's wellbeing, then gave them a new goal that provided clear purpose in the middle of a crisis. The question on the table here is 'is this worth it?', which is a purpose question. Intrinsic motivation (purpose, a sense of calling) is the strongest motivator, and a debrief that turns the flop into a lesson tied to a bigger goal supports it. Best practice blends acknowledging the disappointment with giving direction.", "keyLesson": "Care first, then purpose. Teams recover when they know what they are building toward.", "situationalCaveat": "If the team is simply exhausted, rest and support come first, and direction follows.", "sourceRange": "Question Feedback!A5:J5", "status": "Workbook interpretation; course references need group verification"}, "media": {"stillFilename": "Q4-Disappointing-Event.png", "videoFilename": "q4-setup-v01.mp4", "videoRequired": false, "videoStatus": "not_generated", "alt": "Illustrative paper-theatre scene for After a Disappointing Event.", "sourceFidelityNote": "The image is an illustrative aftermath, not a visual count of the 12 attendees or proof anyone has quit.", "referenceStillPath": "production/reference-stills/Q4-Disappointing-Event.png"}, "sourceRange": "Quiz!A8:G8", "sharedReflection": "Different approaches reveal different trade-offs. Consider what extra information or change in circumstances would alter your response."}, {"id": "Q5", "title": "The Weak Slides", "scenarioText": "Your tutorial group presentation is in 3 days and counts for 30% of the grade. You're the group leader, and one groupmate's slides are well below the standard the rest of you are aiming for. You could redo them in an hour tonight. What are you most likely to do?", "stakes": "Protect a high-stakes presentation without becoming the person who must redo everyone’s work.", "sourceFacts": ["You lead a tutorial group presentation.", "The presentation is in three days.", "It counts for 30% of the grade.", "One groupmate’s slides are below the standard the rest of the group is aiming for.", "You could redo those slides in one hour tonight."], "options": [{"id": "Q5A", "key": "A", "buttonLabel": "Redo the slides yourself tonight", "sourceText": "Redo the slides yourself tonight. It's 30% of the grade and you know they'll be done right.", "buttonLabelStatus": "faithful_short_display_adaptation", "acknowledgement": "You chose: redo the slides yourself tonight.", "feedback": "You protected the grade, but redoing the work teaches little and makes you the bottleneck. It is more reasonable when only hours remain, not when there is time for revision.", "feedbackStatus": "verbatim_workbook", "consequence": "You take control of tonight’s revision; your groupmate may still need help doing it independently.", "consequenceStatus": "proposed_possible_consequence_not_observed_outcome", "reflectionPrompt": "What changes if the presentation is three hours away rather than three days?", "workbookInterpretation": {"style": "Pacesetting", "suggestedForGivenFacts": false, "attribution": "Workbook interpretation, not a validated diagnosis or universal moral score", "sourceCells": {"option": "Quiz!D9", "feedback": "Coding Handoff!H18", "style": "Coding Handoff!F18"}}}, {"id": "Q5B", "key": "B", "buttonLabel": "Reaffirm the group’s standard", "sourceText": "Remind the whole group what standard you're aiming for and why this grade matters, and trust everyone to lift their own part.", "buttonLabelStatus": "faithful_short_display_adaptation", "acknowledgement": "You chose: reaffirm the group’s standard.", "feedback": "You reinforced the group’s goal, but the problem is a specific quality gap. A general reminder may not help the person understand what needs to improve.", "feedbackStatus": "verbatim_workbook", "consequence": "The target is repeated, but your groupmate may still not know how to close the specific quality gap.", "consequenceStatus": "proposed_possible_consequence_not_observed_outcome", "reflectionPrompt": "What changes if the presentation is three hours away rather than three days?", "workbookInterpretation": {"style": "Visionary", "suggestedForGivenFacts": false, "attribution": "Workbook interpretation, not a validated diagnosis or universal moral score", "sourceCells": {"option": "Quiz!E9", "feedback": "Coding Handoff!H19", "style": "Coding Handoff!F19"}}}, {"id": "Q5C", "key": "C", "buttonLabel": "Review together and set a checkpoint", "sourceText": "Sit down with them, go through what works and what doesn't against the marking criteria, and agree a checkpoint tomorrow.", "buttonLabelStatus": "faithful_short_display_adaptation", "acknowledgement": "You chose: review together and set a checkpoint.", "feedback": "You used the marking criteria to make the feedback concrete and added a checkpoint for accountability. This improves the work while building the person’s ability.", "feedbackStatus": "verbatim_workbook", "consequence": "The marking criteria guide the discussion and tomorrow’s checkpoint gives the revision a clear next step.", "consequenceStatus": "proposed_possible_consequence_not_observed_outcome", "reflectionPrompt": "What changes if the presentation is three hours away rather than three days?", "workbookInterpretation": {"style": "Coaching", "suggestedForGivenFacts": true, "attribution": "Workbook interpretation, not a validated diagnosis or universal moral score", "sourceCells": {"option": "Quiz!F9", "feedback": "Coding Handoff!H20", "style": "Coding Handoff!F20"}}}, {"id": "Q5D", "key": "D", "buttonLabel": "Send required changes and a deadline", "sourceText": "Send a clear list of the changes needed, with a deadline tomorrow night.", "buttonLabelStatus": "faithful_short_display_adaptation", "acknowledgement": "You chose: send required changes and a deadline.", "feedback": "You made the required changes clear and protected the deadline. This may secure compliance, but it gives the person less help in understanding how to improve independently.", "feedbackStatus": "verbatim_workbook", "consequence": "The requested edits and deadline are explicit, but the reasoning behind them may remain unclear.", "consequenceStatus": "proposed_possible_consequence_not_observed_outcome", "reflectionPrompt": "What changes if the presentation is three hours away rather than three days?", "workbookInterpretation": {"style": "Commanding", "suggestedForGivenFacts": false, "attribution": "Workbook interpretation, not a validated diagnosis or universal moral score", "sourceCells": {"option": "Quiz!G9", "feedback": "Coding Handoff!H21", "style": "Coding Handoff!F21"}}}], "reflectionPrompt": "What changes if the presentation is three hours away rather than three days?", "workbookInterpretation": {"suggestedOptionId": "Q5C", "style": "Coaching", "concepts": "The delegation trap; coaching and developing people; teaching principles, not just fixing outputs", "caseStudyConnections": "The analyst-turned-manager case and the manager who developed her direct report (both in the Leadership Styles reading); the Marriott case", "rationale": "Think of the manager in the reading who developed a promising employee: she left time to fix problems, worked through drafts together and gave candid feedback, and it paid off. Three days is what makes coaching viable, because it allows one feedback-and-revise cycle. Anchor it to the marking criteria, e.g. 'The slides (situation) have no sources or data (behaviour), which loses marks against the criteria (impact).'", "keyLesson": "Redoing it saves an hour tonight but makes you the bottleneck for every future task. Coach when time allows.", "situationalCaveat": "With 3 hours left, redoing the slides or giving exact instructions can be the right call. The analyst in the reading made the same trade-off; his problem was making it a habit.", "sourceRange": "Question Feedback!A6:J6", "status": "Workbook interpretation; course references need group verification"}, "media": {"stillFilename": "Q5-Weak-Slides.png", "videoFilename": "q5-setup-v01.mp4", "videoRequired": false, "videoStatus": "not_generated", "alt": "Illustrative paper-theatre scene for The Weak Slides.", "sourceFidelityNote": "Abstract slide shapes are illustrative, not evidence of the actual quality defect or marking criteria. Preserve the existing image; readable facts remain in HTML.", "referenceStillPath": "production/reference-stills/Q5-Weak-Slides.png"}, "sourceRange": "Quiz!A9:G9", "sharedReflection": "Different approaches reveal different trade-offs. Consider what extra information or change in circumstances would alter your response."}, {"id": "Q6", "title": "Day One", "scenarioText": "You've been chosen to lead a semester-long Common Core group project. Your four groupmates are mostly strangers from different faculties, and this is your first meeting. What are you most likely to do?", "stakes": "Create a clear, shared start without assigning people roles before understanding them.", "sourceFacts": ["You have been chosen to lead a semester-long Common Core group project.", "You have four groupmates, making five people including you.", "The groupmates are mostly strangers from different faculties.", "This is the first meeting."], "options": [{"id": "Q6A", "key": "A", "buttonLabel": "Agree success, roles and feedback", "sourceText": "Open with what a strong final project looks like, then agree roles, standards and how you'll give each other feedback.", "buttonLabelStatus": "faithful_short_display_adaptation", "acknowledgement": "You chose: agree success, roles and feedback.", "feedback": "You gave a new team a shared picture of success, then clarified roles and feedback. This creates direction without removing everyone’s involvement.", "feedbackStatus": "verbatim_workbook", "consequence": "The new team has a shared picture of success, roles and a way to discuss progress.", "consequenceStatus": "proposed_possible_consequence_not_observed_outcome", "reflectionPrompt": "What should every groupmate be able to explain at the end of the first meeting?", "workbookInterpretation": {"style": "Visionary", "suggestedForGivenFacts": true, "attribution": "Workbook interpretation, not a validated diagnosis or universal moral score", "sourceCells": {"option": "Quiz!D10", "feedback": "Coding Handoff!H22", "style": "Coding Handoff!F22"}}}, {"id": "Q6B", "key": "B", "buttonLabel": "Shape the plan through a brainstorm", "sourceText": "Run an open brainstorm where everyone shapes the topic, roles and schedule together.", "buttonLabelStatus": "faithful_short_display_adaptation", "acknowledgement": "You chose: shape the plan through a brainstorm.", "feedback": "You gave everyone a voice, which can build ownership. Without some structure, though, a first meeting may end with broad ideas but unclear standards and responsibilities.", "feedbackStatus": "verbatim_workbook", "consequence": "Everyone can shape the plan, but the meeting still needs to end with clear responsibilities and standards.", "consequenceStatus": "proposed_possible_consequence_not_observed_outcome", "reflectionPrompt": "What should every groupmate be able to explain at the end of the first meeting?", "workbookInterpretation": {"style": "Democratic", "suggestedForGivenFacts": false, "attribution": "Workbook interpretation, not a validated diagnosis or universal moral score", "sourceCells": {"option": "Quiz!E10", "feedback": "Coding Handoff!H23", "style": "Coding Handoff!F23"}}}, {"id": "Q6C", "key": "C", "buttonLabel": "Send assigned roles before meeting", "sourceText": "Send out a plan with roles and deadlines before the meeting, so the first meeting is about getting started.", "buttonLabelStatus": "faithful_short_display_adaptation", "acknowledgement": "You chose: send assigned roles before meeting.", "feedback": "You created speed and clarity, but assigned roles before learning what people can contribute. This may reduce ownership and place people in unsuitable roles.", "feedbackStatus": "verbatim_workbook", "consequence": "The group can start quickly, but the assigned roles may not fit what each person can contribute.", "consequenceStatus": "proposed_possible_consequence_not_observed_outcome", "reflectionPrompt": "What should every groupmate be able to explain at the end of the first meeting?", "workbookInterpretation": {"style": "Commanding", "suggestedForGivenFacts": false, "attribution": "Workbook interpretation, not a validated diagnosis or universal moral score", "sourceCells": {"option": "Quiz!F10", "feedback": "Coding Handoff!H24", "style": "Coding Handoff!F24"}}}, {"id": "Q6D", "key": "D", "buttonLabel": "Learn strengths before assigning work", "sourceText": "Spend the first week having short one-on-one chats to learn each person's strengths and goals before assigning anything.", "buttonLabelStatus": "faithful_short_display_adaptation", "acknowledgement": "You chose: learn strengths before assigning work.", "feedback": "You took time to understand individual strengths and goals. That is useful, but waiting a full week before setting a shared direction could leave the project behind.", "feedbackStatus": "verbatim_workbook", "consequence": "You learn more about each person while a week passes without an agreed division of work.", "consequenceStatus": "proposed_possible_consequence_not_observed_outcome", "reflectionPrompt": "What should every groupmate be able to explain at the end of the first meeting?", "workbookInterpretation": {"style": "Coaching", "suggestedForGivenFacts": false, "attribution": "Workbook interpretation, not a validated diagnosis or universal moral score", "sourceCells": {"option": "Quiz!G10", "feedback": "Coding Handoff!H25", "style": "Coding Handoff!F25"}}}], "reflectionPrompt": "What should every groupmate be able to explain at the end of the first meeting?", "workbookInterpretation": {"suggestedOptionId": "Q6A", "style": "Visionary", "concepts": "Setting expectations early; the expectation, evaluation, feedback cycle; shared vision", "caseStudyConnections": "The Marriott case study from class (housekeeping inspections); Two Tough Calls (feedback landed well because expectations were clear from the start)", "rationale": "Mismatched or unstated expectations are a common cause of group conflict. For strangers from different faculties, a shared picture of what 'good' looks like gives common ground before the details. This option also agrees roles, standards and a feedback process up front, so expectation, evaluation and feedback are all set on day one.", "keyLesson": "Whatever your style, finish day one with expectations everyone can state back to you.", "situationalCaveat": "If the topic and roles are genuinely open, more collaboration works. If the deadline is tight, a firmer plan may be needed.", "sourceRange": "Question Feedback!A7:J7", "status": "Workbook interpretation; course references need group verification"}, "media": {"stillFilename": "Q6-Day-One.png", "videoFilename": "q6-setup-v01.mp4", "videoRequired": false, "videoStatus": "not_generated", "alt": "Illustrative paper-theatre scene for Day One.", "sourceFidelityNote": "Only four people are visible in the supplied still. The source group is five including the leader; treat the image as a partial view, never change four groupmates to three.", "referenceStillPath": "production/reference-stills/Q6-Day-One.png"}, "sourceRange": "Quiz!A10:G10", "sharedReflection": "Different approaches reveal different trade-offs. Consider what extra information or change in circumstances would alter your response."}, {"id": "Q7", "title": "Influence Without a Title", "scenarioText": "You're a regular society member, not on the exec. You think moving event sign-ups from paper to an online form would boost attendance, but the exec has always done it the old way. What are you most likely to do?", "stakes": "Win support for an untested improvement when you do not have formal authority.", "sourceFacts": ["You are an ordinary society member, not on the executive committee.", "Event sign-ups currently use paper.", "You think an online form would improve attendance; that is a proposal, not a proven result.", "The executive committee has always used the existing method."], "options": [{"id": "Q7A", "key": "A", "buttonLabel": "Build relationships with the exec", "sourceText": "Get to know a few exec members informally first, then raise the idea once they know and trust you.", "buttonLabelStatus": "faithful_short_display_adaptation", "acknowledgement": "You chose: build relationships with the exec.", "feedback": "You focused on trust and relationships, which can make others more open to your idea. On its own, though, this approach is slow and does not show whether the change will work.", "feedbackStatus": "verbatim_workbook", "consequence": "Trust may make the proposal easier to hear, but it does not yet show that the new method works.", "consequenceStatus": "proposed_possible_consequence_not_observed_outcome", "reflectionPrompt": "What would make the change easier for the executive committee to trust?", "workbookInterpretation": {"style": "Affiliative", "suggestedForGivenFacts": false, "attribution": "Workbook interpretation, not a validated diagnosis or universal moral score", "sourceCells": {"option": "Quiz!D11", "feedback": "Coding Handoff!H26", "style": "Coding Handoff!F26"}}}, {"id": "Q7B", "key": "B", "buttonLabel": "Gather member support with a poll", "sourceText": "Collect support from other members with a quick poll, then present the idea as a request from many members.", "buttonLabelStatus": "faithful_short_display_adaptation", "acknowledgement": "You chose: gather member support with a poll.", "feedback": "You showed that others support the idea, but interest is not the same as evidence. The executive team may also see the poll as pressure rather than collaboration.", "feedbackStatus": "verbatim_workbook", "consequence": "Member support becomes visible, but the executive committee may still want evidence of effectiveness.", "consequenceStatus": "proposed_possible_consequence_not_observed_outcome", "reflectionPrompt": "What would make the change easier for the executive committee to trust?", "workbookInterpretation": {"style": "Democratic", "suggestedForGivenFacts": false, "attribution": "Workbook interpretation, not a validated diagnosis or universal moral score", "sourceCells": {"option": "Quiz!E11", "feedback": "Coding Handoff!H27", "style": "Coding Handoff!F27"}}}, {"id": "Q7C", "key": "C", "buttonLabel": "Pitch an inspiring direction", "sourceText": "Prepare a short, inspiring pitch about where the society could go and present it at the next general meeting.", "buttonLabelStatus": "faithful_short_display_adaptation", "acknowledgement": "You chose: pitch an inspiring direction.", "feedback": "You offered an engaging direction, but a strong pitch still asks the team to accept an untested change. Evidence would make the idea easier to support.", "feedbackStatus": "verbatim_workbook", "consequence": "The idea gains a clear purpose, but the change remains untested.", "consequenceStatus": "proposed_possible_consequence_not_observed_outcome", "reflectionPrompt": "What would make the change easier for the executive committee to trust?", "workbookInterpretation": {"style": "Visionary", "suggestedForGivenFacts": false, "attribution": "Workbook interpretation, not a validated diagnosis or universal moral score", "sourceCells": {"option": "Quiz!F11", "feedback": "Coding Handoff!H28", "style": "Coding Handoff!F28"}}}, {"id": "Q7D", "key": "D", "buttonLabel": "Run a small trial and bring evidence", "sourceText": "Offer to run the online form for one small upcoming event and bring the sign-up numbers to the exec.", "buttonLabelStatus": "faithful_short_display_adaptation", "acknowledgement": "You chose: run a small trial and bring evidence.", "feedback": "You lowered the risk by offering a small trial and taking responsibility for it. The results give you credibility even without a formal title.", "feedbackStatus": "verbatim_workbook", "consequence": "A small trial creates evidence to discuss, without guaranteeing higher attendance.", "consequenceStatus": "proposed_possible_consequence_not_observed_outcome", "reflectionPrompt": "What would make the change easier for the executive committee to trust?", "workbookInterpretation": {"style": "Pacesetting", "suggestedForGivenFacts": true, "attribution": "Workbook interpretation, not a validated diagnosis or universal moral score", "sourceCells": {"option": "Quiz!G11", "feedback": "Coding Handoff!H29", "style": "Coding Handoff!F29"}}}], "reflectionPrompt": "What would make the change easier for the executive committee to trust?", "workbookInterpretation": {"suggestedOptionId": "Q7D", "style": "Pacesetting", "concepts": "The seven bases of power (expert, information, connection, referent, legitimate, reward, coercive); influence without a title", "caseStudyConnections": "The Sunand Menon case (credibility from doing the work; relationships as influence); the Martin Luther King Jr. case (influence beyond formal title)", "rationale": "You have no legitimate power (a title), so you build expert and information power. A small trial produces evidence and lowers the risk of saying yes, since the exec can see it work without committing. The Menon case makes the same point: nothing builds credibility like someone willing to do the hard work.", "keyLesson": "Without a title, results and relationships are your currency. The strongest real-world move is often a trial plus relationship-building.", "situationalCaveat": "If the exec is resistant to any change, building relationships first may be needed.", "sourceRange": "Question Feedback!A8:J8", "status": "Workbook interpretation; course references need group verification"}, "media": {"stillFilename": "Q7-Influence-Without-Title.png", "videoFilename": "q7-setup-v01.mp4", "videoRequired": false, "videoStatus": "not_generated", "alt": "Illustrative paper-theatre scene for Influence Without a Title.", "sourceFidelityNote": "The visible tablet illustrates the proposed change; it does not prove a trial occurred or increased attendance. Do not animate a successful demonstration before selection.", "referenceStillPath": "production/reference-stills/Q7-Influence-Without-Title.png"}, "sourceRange": "Quiz!A11:G11", "sharedReflection": "Different approaches reveal different trade-offs. Consider what extra information or change in circumstances would alter your response."}, {"id": "Q8", "title": "The Loudest Voice", "scenarioText": "At your hall committee's weekly meeting, one person talks over everyone, while the first-years who recently joined barely say a word. What are you most likely to do?", "stakes": "Make participation possible without letting one voice determine the whole meeting.", "sourceFacts": ["This is a hall committee’s weekly meeting.", "One person talks over others.", "First-years who recently joined barely speak."], "options": [{"id": "Q8A", "key": "A", "buttonLabel": "Ask the dominant speaker to pause", "sourceText": "Step in during the meeting and ask them to hold back so others can speak.", "buttonLabelStatus": "faithful_short_display_adaptation", "acknowledgement": "You chose: ask the dominant speaker to pause.", "feedback": "You stopped the interruption quickly, but correcting someone publicly may create defensiveness. It also does not help quieter members prepare to contribute next time.", "feedbackStatus": "verbatim_workbook", "consequence": "The interruption stops for now, but quieter members still need a reliable way to prepare and contribute.", "consequenceStatus": "proposed_possible_consequence_not_observed_outcome", "reflectionPrompt": "How can the meeting itself make room for someone who does not speak easily on the spot?", "workbookInterpretation": {"style": "Commanding", "suggestedForGivenFacts": false, "attribution": "Workbook interpretation, not a validated diagnosis or universal moral score", "sourceCells": {"option": "Quiz!D12", "feedback": "Coding Handoff!H30", "style": "Coding Handoff!F30"}}}, {"id": "Q8B", "key": "B", "buttonLabel": "Share an agenda and give turns", "sourceText": "Circulate the agenda beforehand and give each person a few minutes to speak in turn.", "buttonLabelStatus": "faithful_short_display_adaptation", "acknowledgement": "You chose: share an agenda and give turns.", "feedback": "You changed the meeting structure so everyone has a fair chance to prepare and speak. This addresses the group dynamic without singling anyone out.", "feedbackStatus": "verbatim_workbook", "consequence": "Everyone gets preparation time and a speaking turn; follow-through still matters.", "consequenceStatus": "proposed_possible_consequence_not_observed_outcome", "reflectionPrompt": "How can the meeting itself make room for someone who does not speak easily on the spot?", "workbookInterpretation": {"style": "Democratic", "suggestedForGivenFacts": true, "attribution": "Workbook interpretation, not a validated diagnosis or universal moral score", "sourceCells": {"option": "Quiz!E12", "feedback": "Coding Handoff!H31", "style": "Coding Handoff!F31"}}}, {"id": "Q8C", "key": "C", "buttonLabel": "Hear quieter members afterwards", "sourceText": "Check in with the quieter members after the meeting and encourage them to share their ideas with you.", "buttonLabelStatus": "faithful_short_display_adaptation", "acknowledgement": "You chose: hear quieter members afterwards.", "feedback": "You made quieter members feel heard, but their ideas still do not reach the group directly. This is helpful support, not a full solution to the meeting dynamic.", "feedbackStatus": "verbatim_workbook", "consequence": "Quieter members are heard privately, but their ideas may still be missing from the shared discussion.", "consequenceStatus": "proposed_possible_consequence_not_observed_outcome", "reflectionPrompt": "How can the meeting itself make room for someone who does not speak easily on the spot?", "workbookInterpretation": {"style": "Affiliative", "suggestedForGivenFacts": false, "attribution": "Workbook interpretation, not a validated diagnosis or universal moral score", "sourceCells": {"option": "Quiz!F12", "feedback": "Coding Handoff!H32", "style": "Coding Handoff!F32"}}}, {"id": "Q8D", "key": "D", "buttonLabel": "Coach the dominant speaker privately", "sourceText": "Talk privately to the loud member about how it comes across and help them make more room for others.", "buttonLabelStatus": "faithful_short_display_adaptation", "acknowledgement": "You chose: coach the dominant speaker privately.", "feedback": "You addressed the behavior privately and gave the person a chance to improve. This can help, though meeting structure is still needed to support quieter voices.", "feedbackStatus": "verbatim_workbook", "consequence": "The dominant speaker receives private feedback; the meeting may also need a better participation structure.", "consequenceStatus": "proposed_possible_consequence_not_observed_outcome", "reflectionPrompt": "How can the meeting itself make room for someone who does not speak easily on the spot?", "workbookInterpretation": {"style": "Coaching", "suggestedForGivenFacts": false, "attribution": "Workbook interpretation, not a validated diagnosis or universal moral score", "sourceCells": {"option": "Quiz!G12", "feedback": "Coding Handoff!H33", "style": "Coding Handoff!F33"}}}], "reflectionPrompt": "How can the meeting itself make room for someone who does not speak easily on the spot?", "workbookInterpretation": {"suggestedOptionId": "Q8B", "style": "Democratic", "concepts": "Inclusive meeting structure; making room for quieter voices; Democratic style", "caseStudyConnections": "The guest lecture on diversity and inclusion (UN); the R&D talent case (people who want a say engage more when the system gives them one)", "rationale": "The guest speaker's tools for keeping the loudest voices from dominating were noticing people, nudging, sharing the agenda in advance so people can prepare (not everyone speaks well on the spot), and creating structure such as 2-3 minutes each. Structure fixes the problem by design, for everyone, without singling anyone out. It particularly helps first-years, who face a hierarchy barrier, and introverts, who need preparation time.", "keyLesson": "Fix the room, not just the person.", "situationalCaveat": "If one person's behaviour continues despite structure, a private conversation is the next step.", "sourceRange": "Question Feedback!A9:J9", "status": "Workbook interpretation; course references need group verification"}, "media": {"stillFilename": "Q8-Loudest-Voice.png", "videoFilename": "q8-setup-v01.mp4", "videoRequired": false, "videoStatus": "not_generated", "alt": "Illustrative paper-theatre scene for The Loudest Voice.", "sourceFidelityNote": "Character roles are fictional staging; do not infer anyone’s ability or leadership style from appearance.", "referenceStillPath": "production/reference-stills/Q8-Loudest-Voice.png"}, "sourceRange": "Quiz!A12:G12", "sharedReflection": "Different approaches reveal different trade-offs. Consider what extra information or change in circumstances would alter your response."}, {"id": "Q9", "title": "Friend vs. Better Candidate", "scenarioText": "You’re on the selection panel for next year’s society committee. Your close friend has been reliable behind the scenes and works well with the team, but another applicant gave a stronger interview and has more relevant experience. Everyone knows you and your friend are close. What are you most likely to do?", "stakes": "Make a defensible selection when your personal relationship may affect judgment.", "sourceFacts": ["You are on the selection panel for next year’s society committee.", "Your close friend has been reliable behind the scenes and works well with the team.", "Another applicant gave a stronger interview and has more relevant experience.", "Everyone knows you and your friend are close."], "options": [{"id": "Q9A", "key": "A", "buttonLabel": "Back your friend’s proven teamwork", "sourceText": "Support your friend because trust, reliability and team chemistry matter, even if those strengths were less visible in the interview.", "buttonLabelStatus": "faithful_short_display_adaptation", "acknowledgement": "You chose: back your friend’s proven teamwork.", "feedback": "You valued trust and proven reliability, which are relevant to teamwork. The risk is giving extra weight to qualities that favor someone you already know unless the panel agreed on them beforehand.", "feedbackStatus": "verbatim_workbook", "consequence": "You recognize real teamwork strengths, but the panel must guard against giving friendship extra weight.", "consequenceStatus": "proposed_possible_consequence_not_observed_outcome", "reflectionPrompt": "Would you defend the same criteria if the applicants’ names were hidden?", "workbookInterpretation": {"style": "Affiliative", "suggestedForGivenFacts": false, "attribution": "Workbook interpretation, not a validated diagnosis or universal moral score", "sourceCells": {"option": "Quiz!D13", "feedback": "Coding Handoff!H34", "style": "Coding Handoff!F34"}}}, {"id": "Q9B", "key": "B", "buttonLabel": "Recommend immediate experience", "sourceText": "Recommend the more experienced applicant and explain clearly that the role needs someone who can contribute immediately.", "buttonLabelStatus": "faithful_short_display_adaptation", "acknowledgement": "You chose: recommend immediate experience.", "feedback": "You prioritized immediate capability and made a clear recommendation. The choice may be reasonable, but a transparent panel process is especially important because of your personal connection.", "feedbackStatus": "verbatim_workbook", "consequence": "You prioritize immediate capability, but a transparent selection process is still needed.", "consequenceStatus": "proposed_possible_consequence_not_observed_outcome", "reflectionPrompt": "Would you defend the same criteria if the applicants’ names were hidden?", "workbookInterpretation": {"style": "Commanding", "suggestedForGivenFacts": false, "attribution": "Workbook interpretation, not a validated diagnosis or universal moral score", "sourceCells": {"option": "Quiz!E13", "feedback": "Coding Handoff!H35", "style": "Coding Handoff!F35"}}}, {"id": "Q9C", "key": "C", "buttonLabel": "Back your friend with development", "sourceText": "Support your friend and offer to help them build the skills they would need to grow into the role.", "buttonLabelStatus": "faithful_short_display_adaptation", "acknowledgement": "You chose: back your friend with development.", "feedback": "You focused on long-term potential and development. However, a development plan should not replace fair selection criteria or disadvantage the stronger candidate.", "feedbackStatus": "verbatim_workbook", "consequence": "You invest in potential, but a development promise does not itself make the selection fair.", "consequenceStatus": "proposed_possible_consequence_not_observed_outcome", "reflectionPrompt": "Would you defend the same criteria if the applicants’ names were hidden?", "workbookInterpretation": {"style": "Coaching", "suggestedForGivenFacts": false, "attribution": "Workbook interpretation, not a validated diagnosis or universal moral score", "sourceCells": {"option": "Quiz!F13", "feedback": "Coding Handoff!H36", "style": "Coding Handoff!F36"}}}, {"id": "Q9D", "key": "D", "buttonLabel": "Agree criteria and score both fairly", "sourceText": "Agree the selection criteria and their weighting with the panel, then score both applicants against the same standard.", "buttonLabelStatus": "faithful_short_display_adaptation", "acknowledgement": "You chose: agree criteria and score both fairly.", "feedback": "You made the process more transparent by agreeing on criteria before scoring either person. This helps the panel weigh experience, reliability and team fit consistently.", "feedbackStatus": "verbatim_workbook", "consequence": "The panel compares both candidates consistently; the process does not predetermine who wins.", "consequenceStatus": "proposed_possible_consequence_not_observed_outcome", "reflectionPrompt": "Would you defend the same criteria if the applicants’ names were hidden?", "workbookInterpretation": {"style": "Democratic", "suggestedForGivenFacts": true, "attribution": "Workbook interpretation, not a validated diagnosis or universal moral score", "sourceCells": {"option": "Quiz!G13", "feedback": "Coding Handoff!H37", "style": "Coding Handoff!F37"}}}], "reflectionPrompt": "Would you defend the same criteria if the applicants’ names were hidden?", "workbookInterpretation": {"suggestedOptionId": "Q9D", "style": "Democratic", "concepts": "Affinity bias; System 1 vs System 2 thinking; meritocracy; process over outcome", "caseStudyConnections": "Two Tough Calls (hiring through friendship); the Prime Toys diversity hiring case; the Assigned Leader mini-case about favouritism", "rationale": "Three readings point the same way. In Two Tough Calls, one employee was hired through the CEO's friendship despite failing his interviews, and the manager admits she tends to hire people like herself (affinity bias). In the Prime Toys case, the CEO trusts a board of friends with similar backgrounds, and 'diversity' was never clearly defined, which made the hiring decision hard to defend. Choosing your friend is a fast, intuitive System 1 call. A rubric forces slower System 2 thinking and supports meritocracy. You can never know the counterfactual, so the quality of the process is what you control, and with a shared rubric nobody, including you, can doubt it.", "keyLesson": "When you're personally involved, agree the criteria first.", "situationalCaveat": "If criteria are agreed in advance and trust or team fit is one of them, it is a legitimate factor.", "sourceRange": "Question Feedback!A10:J10", "status": "Workbook interpretation; course references need group verification"}, "media": {"stillFilename": "Q9-Friend-Versus-Better-Candidate.png", "videoFilename": "q9-setup-v01.mp4", "videoRequired": false, "videoStatus": "not_generated", "alt": "Illustrative paper-theatre scene for Friend vs. Better Candidate.", "sourceFidelityNote": "Two identical folders preserve neutral candidate status. Do not identify merit or competence from appearance, light, costume or the visible friend.", "referenceStillPath": "production/reference-stills/Q9-Friend-Versus-Better-Candidate.png"}, "sourceRange": "Quiz!A13:G13", "sharedReflection": "Different approaches reveal different trade-offs. Consider what extra information or change in circumstances would alter your response."}]};
